dunes-script-module.script:
const method = "POST";
const url = "/v1/sddcs"; // ?skipValidations=true";
const contentType = "application/json"



var request = restHost.createRequest(method, url, sddcSpec);
request.contentType = contentType;
request.setHeader("Authorization", "Bearer " + installerToken);

var response = request.execute();


var statusCode = response.statusCode;
var statusCodeAttribute = statusCode;
System.log("Status code: " + statusCode);
var contentLength = response.contentLength;
var headers = response.getAllHeaders();
var contentAsString = response.contentAsString;

return JSON.parse(contentAsString);
